#!/usr/bin/env python3
"""Generate shared CSS custom properties from design/tokens.json."""

from __future__ import annotations

import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
TOKENS = ROOT / "design" / "tokens.json"
OUT_CV = ROOT / "css" / "design-tokens.css"
OUT_HUGO = ROOT / "hugo" / "assets" / "design-tokens.css"

HEADER = """\
/* Generated by scripts/build/sync_design_tokens.py — do not edit by hand.
 * Source: design/tokens.json (shared spine; different density per surface).
 */
"""


def css_block(tokens: dict) -> str:
    spine = tokens["colors"]["spine"]
    focus = tokens["focus"]
    space = tokens["space"]
    radius = tokens["radius"]
    docs_light = tokens["colors"]["docs"]["light"]
    docs_dark = tokens["colors"]["docs"]["dark"]
    hero = tokens["colors"]["hero"]
    typo = tokens["typography"]
    button = tokens["components"]["button"]
    badge = tokens["components"]["badge"]
    lines = [
        HEADER,
        ":root {",
        f"  --spine-accent: {spine['accent']};",
        f"  --spine-accent-soft: {spine['accent-soft']};",
        f"  --spine-ink: {spine['ink']};",
        f"  --spine-muted: {spine['muted']};",
        f"  --spine-focus: {focus['color']};",
        f"  --spine-focus-width: {focus['width']};",
        f"  --spine-focus-offset: {focus['offset']};",
        f"  --space-1: {space['1']};",
        f"  --space-2: {space['2']};",
        f"  --space-3: {space['3']};",
        f"  --space-4: {space['4']};",
        f"  --space-5: {space['5']};",
        f"  --space-6: {space['6']};",
        f"  --radius-sm: {radius['sm']};",
        f"  --radius-md: {radius['md']};",
        f"  --radius-lg: {radius['lg']};",
        f"  --type-display: {typo['display']['family']};",
        f"  --type-body: {typo['body']['family']};",
        f"  --type-docs: {typo['docs']['family']};",
        f"  --type-code: {typo['docs']['codeFamily']};",
        f"  --type-body-size: {typo['body']['size']};",
        f"  --type-docs-size: {typo['docs']['size']};",
        f"  --type-code-size: {typo['docs']['codeSize']};",
        f"  --prose-measure: {typo['docs']['measure']};",
        f"  --btn-min-height: {button['minHeight']};",
        f"  --btn-radius: {button['radius']};",
        f"  --badge-radius: {badge['radius']};",
        f"  --hero-canvas: {hero['canvas']};",
        f"  --hero-paper: {hero['paper']};",
        f"  --hero-ink: {hero['ink']};",
        f"  --hero-muted: {hero['muted']};",
        f"  --hero-accent: {hero['accent']};",
        f"  --hero-soft: {hero['soft']};",
        f"  --hero-rule: {hero['rule']};",
        f"  --hero-glow: {hero['glow']};",
        f"  --motion-ease-out: {tokens['motion']['ease-out']};",
        f"  --motion-ease-in-out: {tokens['motion']['ease-in-out']};",
        f"  --motion-ease-editorial: {tokens['motion']['ease-editorial']};",
        f"  --motion-duration-fast: {tokens['motion']['duration-fast']};",
        f"  --motion-duration-enter: {tokens['motion']['duration-enter']};",
        f"  --motion-duration-ignite: {tokens['motion']['duration-ignite']};",
        f"  --docs-bg: {docs_light['bg']};",
        f"  --docs-panel: {docs_light['panel']};",
        f"  --docs-text: {docs_light['text']};",
        f"  --docs-muted: {docs_light['muted']};",
        f"  --docs-accent: {docs_light['accent']};",
        f"  --docs-accent2: {docs_light['accent2']};",
        f"  --docs-line: {docs_light['line']};",
        "}",
        "",
        "html.dark {",
        f"  --docs-bg: {docs_dark['bg']};",
        f"  --docs-panel: {docs_dark['panel']};",
        f"  --docs-text: {docs_dark['text']};",
        f"  --docs-muted: {docs_dark['muted']};",
        f"  --docs-accent: {docs_dark['accent']};",
        f"  --docs-accent2: {docs_dark['accent2']};",
        f"  --docs-line: {docs_dark['line']};",
        "}",
        "",
        "/* Shared focus treatment across CV hero and Hugo surfaces */",
        "a:focus-visible,",
        "button:focus-visible,",
        "input:focus-visible,",
        "select:focus-visible,",
        "summary:focus-visible,",
        ".cv-site-nav a:focus-visible,",
        ".cv-nav-lang a:focus-visible,",
        ".site-header a:focus-visible,",
        ".site-header button:focus-visible {",
        "  outline: var(--spine-focus-width) solid var(--spine-focus);",
        "  outline-offset: var(--spine-focus-offset);",
        "}",
        "",
    ]
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check",
        action="store_true",
        help="Exit 1 if generated CSS would differ from committed files",
    )
    args = parser.parse_args()
    tokens = json.loads(TOKENS.read_text(encoding="utf-8"))
    css = css_block(tokens)
    if args.check:
        for path in (OUT_CV, OUT_HUGO):
            if not path.exists() or path.read_text(encoding="utf-8") != css:
                print(f"outdated: {path.relative_to(ROOT)}")
                return 1
        print("design tokens in sync")
        return 0
    OUT_CV.parent.mkdir(parents=True, exist_ok=True)
    OUT_HUGO.parent.mkdir(parents=True, exist_ok=True)
    OUT_CV.write_text(css, encoding="utf-8", newline="\n")
    OUT_HUGO.write_text(css, encoding="utf-8", newline="\n")
    print(f"wrote {OUT_CV.relative_to(ROOT)}")
    print(f"wrote {OUT_HUGO.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
